package online.springshop.api.modules.auth.domain.useraction.valueobject;

import lombok.Getter;
import online.springshop.api.modules.auth.domain.useraction.exception.ConfirmationCodeError;
import online.springshop.api.modules.auth.domain.useraction.exception.InvalidConfirmationCodeException;
import online.springshop.api.modules.auth.domain.useraction.policy.ConfirmationCodePolicy;
import online.springshop.api.shared.result.Result;
import online.springshop.api.shared.result.ResultError;

/**
 * Raw numeric code submitted to or generated by the confirmation workflow.
 * Instances retain leading zeroes and therefore store the code as a string.
 */
public final class ConfirmationCode
{
    @Getter
    private final String value;

    private ConfirmationCode (String value)
    {
        this.value = value;
    }

    /**
     * Creates a confirmation code from untrusted input, such as a value received
     * in an API request.
     *
     * @param value the untrusted raw code
     * @return a validated confirmation code
     * @throws InvalidConfirmationCodeException when the value violates the code policy
     */
    public static ConfirmationCode of (String value)
    {
        Result<Void, ConfirmationCodeError> result = validate(value);

        if (result.isFailure())
            throw new InvalidConfirmationCodeException(result.error().message(), result.error().code());

        return new ConfirmationCode(value);
    }

    /**
     * Creates a confirmation code from a value generated inside the API.
     * Generated values are still checked so an invalid generator configuration
     * fails immediately.
     *
     * @param value the API-generated raw code
     * @return the generated confirmation code
     * @throws NullPointerException when the generated value is {@code null}
     * @throws IllegalArgumentException when the generated value violates the code policy
     */
    public static ConfirmationCode from (String value)
    {
        Result<Void, ConfirmationCodeError> result = validate(value);

        if (result.isSuccess())
            return new ConfirmationCode(value);

        if (result.error().code() == ConfirmationCodeError.IS_NULL)
            throw new NullPointerException(result.error().message());

        throw new IllegalArgumentException(result.error().message());
    }

    private static Result<Void, ConfirmationCodeError> validate (String value)
    {
        if (value == null)
            return Result.failure(
                new ResultError<>("Confirmation code value must not be null", ConfirmationCodeError.IS_NULL)
            );

        if (value.isBlank())
            return Result.failure(
                new ResultError<>("Confirmation code value must not be blank", ConfirmationCodeError.IS_BLANK)
            );

        if (value.length() != ConfirmationCodePolicy.LENGTH)
            return Result.failure(
                new ResultError<>(
                    "Confirmation code must have exactly %s characters".formatted(ConfirmationCodePolicy.LENGTH),
                    ConfirmationCodeError.HAS_INVALID_LENGTH)
            );

        for (char c : value.toCharArray())
            if (c < '0' || c > '9')
                return Result.failure(
                    new ResultError<>("Confirmation code must have only numbers", ConfirmationCodeError.HAS_INVALID_CHARACTERS)
                );

        return Result.success();
    }

    @Override
    public boolean equals (Object object)
    {
        if (this == object)
            return true;

        if (!(object instanceof ConfirmationCode that))
            return false;

        return value.equals(that.value);
    }

    @Override
    public int hashCode ()
    {
        return value.hashCode();
    }
}
